#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    bool subsequence = false;
    size_t j = 0;

    for (char c : s) {
        if (j < t.size() && c == t[j]) {
            ++j;
        }
    }
    subsequence = (j == t.size());

    int cnt[26] = {};
    for (char c : s) {
        ++cnt[c - 'a'];
    }
    for (char c : t) {
        --cnt[c - 'a'];
    }

    bool enough = true;
    bool sameCounts = true;

    for (int x : cnt) {
        enough &= (x >= 0);
        sameCounts &= (x == 0);
    }

    if (subsequence)
        cout << "automaton";
    else if (sameCounts)
        cout << "array";
    else if (enough)
        cout << "both";
    else
        cout << "need tree";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    size_t j = 0;
    for (char c : s) {
        if (j < t.size() && c == t[j]) {
            ++j;
        }
    }

    if (j == t.size()) {
        cout << "automaton";
        return 0;
    }

    array<int, 26> count{};
    for (char c : s) ++count[c - 'a'];
    for (char c : t) --count[c - 'a'];

    bool enough = true;
    bool equal = true;

    for (int value : count) {
        if (value < 0) enough = false;
        if (value != 0) equal = false;
    }

    if (equal)
        cout << "array";
    else if (enough)
        cout << "both";
    else
        cout << "need tree";

    return 0;
}

